import React from 'react';
import classNames from 'classnames';
import styles from './Subline.module.scss';

interface Props {
  theme: {
    fontSize: {
      small: number;
      big: number;
    };
    colors: {
      white: string;
      grey: {
        light: string;
      };
    };
  };
  sectionTitle: string;
  light: boolean;
  children?: React.ReactNode;
}

const Subline: React.FC<Props> = ({ theme, sectionTitle, light, children }) => {
  const styleVars: React.CSSProperties = {
    // Set font size from theme
    ['--subline-font-size' as any]: theme.fontSize.small,
    // Set light color from theme if needed
    ...(light && { ['--subline-light-color' as any]: `rgba(${parseInt(theme.colors.white.slice(1,3),16)},${parseInt(theme.colors.white.slice(3,5),16)},${parseInt(theme.colors.white.slice(5,7),16)},0.7)` })
  };

  return (
    <div
      className={classNames(
        styles.subline,
        { [styles.light]: light },
        { [styles.sectionTitle]: sectionTitle }
      )}
      style={styleVars}
    >
      {children}
    </div>
  );
};

export default Subline;
